PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('staff','manager','admin')), store TEXT NOT NULL, job TEXT NOT NULL, stations TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),csrf TEXT NOT NULL,expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset REAL NOT NULL);
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY,store TEXT NOT NULL,title TEXT NOT NULL,kind TEXT NOT NULL,jobs TEXT NOT NULL,stations TEXT NOT NULL,aliases TEXT NOT NULL,risk INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS revisions(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES documents(id),version INTEGER NOT NULL,state TEXT NOT NULL,content TEXT NOT NULL,source TEXT NOT NULL,effective_at TEXT,expires_at TEXT,created_by INTEGER REFERENCES users(id),approved_by INTEGER REFERENCES users(id),approved_at TEXT,UNIQUE(document_id,version));
CREATE TRIGGER IF NOT EXISTS immutable_approved BEFORE UPDATE ON revisions WHEN OLD.approved_at IS NOT NULL AND (NEW.content<>OLD.content OR NEW.source<>OLD.source OR NEW.effective_at IS NOT OLD.effective_at OR NEW.expires_at IS NOT OLD.expires_at OR NEW.document_id<>OLD.document_id OR NEW.version<>OLD.version OR NEW.approved_by IS NOT OLD.approved_by OR NEW.approved_at IS NOT OLD.approved_at OR NEW.created_by<>OLD.created_by OR NEW.state<>'retired') BEGIN SELECT RAISE(ABORT,'Approved revision is immutable'); END;
CREATE TRIGGER IF NOT EXISTS no_delete_approved BEFORE DELETE ON revisions WHEN OLD.approved_at IS NOT NULL BEGIN SELECT RAISE(ABORT,'Approved revision is immutable'); END;
CREATE TABLE IF NOT EXISTS queries(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),store TEXT NOT NULL,station TEXT NOT NULL,question TEXT NOT NULL,revision_ids TEXT NOT NULL,resolved INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback(id INTEGER PRIMARY KEY,query_id INTEGER NOT NULL REFERENCES queries(id),user_id INTEGER REFERENCES users(id),kind TEXT NOT NULL,description TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'open',resolution TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS modules(id INTEGER PRIMARY KEY,store TEXT NOT NULL,title TEXT NOT NULL,objective TEXT NOT NULL,revision_ids TEXT NOT NULL,quiz TEXT NOT NULL,pass_score INTEGER NOT NULL,created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS assignments(id INTEGER PRIMARY KEY,module_id INTEGER NOT NULL REFERENCES modules(id),user_id INTEGER NOT NULL REFERENCES users(id),assigned_by INTEGER REFERENCES users(id),best_score INTEGER,practical_by INTEGER REFERENCES users(id),practical_note TEXT,practical_at TEXT,UNIQUE(module_id,user_id));
CREATE TABLE IF NOT EXISTS attempts(id INTEGER PRIMARY KEY,assignment_id INTEGER REFERENCES assignments(id),score INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,store TEXT NOT NULL,actor INTEGER REFERENCES users(id),action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT NOT NULL);
